p.write_text('''def transform(grid):
    h, w = len(grid), len(grid[0])
    full = set()
    for r in range(h):
        if len(set(grid[r])) == 1: full.add(grid[r][0])
    for c in range(w):
        vals = {grid[r][c] for r in range(h)}
        if len(vals) == 1: full.add(next(iter(vals)))
    # The repeated line color is the one to highlight.
    color = next(iter(full))
    marked = set()
    for r in range(h):
        if all(x == color for x in grid[r]): marked.update((r,c) for c in range(w))
    for c in range(w):
        if all(grid[r][c] == color for r in range(h)): marked.update((r,c) for r in range(h))
    out = [row[:] for row in grid]
    for r,c in marked: out[r][c] = 2
    return out
''')
